import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import Docxtemplater from "docxtemplater";
import PizZip from "pizzip";
import { STANDARD_TEMPLATE_ID } from "./template";
import type { ResumeViewModel } from "./viewModel";

/**
 * DOCX renderer (new capability; the oracle produces HTML/PDF only).
 *
 * Uses `docxtemplater` with the trusted checked-in template
 * (`templates/mouad_standard_v1.docx`, generated by
 * `scripts/build-docx-template.mjs`). The template ID allow-list is the
 * same single standard template as HTML: the job description can never
 * select a template. Data substituted into the template is the canonical
 * view model only — docxtemplater escapes XML entities in values, so
 * hostile text cannot break document structure.
 */

export const DOCX_TEMPLATE_ID = STANDARD_TEMPLATE_ID;
export const DOCX_TEMPLATE_VERSION = "v1";
export const DOCX_MEDIA_TYPE =
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document";

export function loadDocxTemplateBytes(): Buffer {
  const path = fileURLToPath(new URL("./templates/mouad_standard_v1.docx", import.meta.url));
  return readFileSync(path);
}

export function docxTemplateHash(templateBytes: Buffer): string {
  return createHash("sha256").update(templateBytes).digest("hex");
}

interface DocxJob {
  company: string;
  dates: string;
  role: string;
  location: string;
  bullets: Array<{ text: string }>;
}

function toDocxJob(job: ResumeViewModel["professional_experience"][number]): DocxJob {
  return {
    company: job.company,
    dates: job.dates,
    role: job.role,
    location: job.location,
    bullets: job.bullets.map((text) => ({ text })),
  };
}

/** Flatten the view model to the template's tag namespace. */
export function docxTemplateData(viewModel: ResumeViewModel): Record<string, unknown> {
  return {
    full_name: viewModel.header.full_name,
    contact_line: viewModel.header.contact_parts.map((part) => part.text).join(" | "),
    has_summary: viewModel.summary_copy !== "",
    summary_copy: viewModel.summary_copy,
    has_professional: viewModel.professional_experience.length > 0,
    professional_experience: viewModel.professional_experience.map(toDocxJob),
    has_earlier: viewModel.earlier_career.length > 0,
    earlier_career: viewModel.earlier_career.map(toDocxJob),
    has_skills: viewModel.skill_rows.length > 0,
    skill_rows: viewModel.skill_rows.map((row) => ({ label: row.label, terms: row.terms.join(", ") })),
    has_education: viewModel.education_rows.length > 0,
    education_rows: viewModel.education_rows.map((edu) => ({
      line: edu.dates !== "" ? `${edu.detail} (${edu.dates})` : edu.detail,
    })),
  };
}

/** Render the view model to a DOCX buffer. Throws on template/data errors. */
export function renderDocx(viewModel: ResumeViewModel, templateBytes: Buffer): Buffer {
  let zip: PizZip;
  try {
    zip = new PizZip(templateBytes);
  } catch (error) {
    throw new Error(`Invalid DOCX template archive: ${(error as Error).message}`);
  }
  const document = new Docxtemplater(zip, { paragraphLoop: true, linebreaks: true });
  try {
    document.render(docxTemplateData(viewModel));
  } catch (error) {
    throw new Error(`DOCX template render failed: ${(error as Error).message}`);
  }
  return document.getZip().generate({ type: "nodebuffer", compression: "DEFLATE" });
}

/**
 * Extract paragraph texts from a DOCX buffer for parity checks. Runs are
 * joined without separators inside a paragraph (Word splits text across
 * runs arbitrarily); paragraphs stay separate entries.
 */
export function extractDocxParagraphs(docxBytes: Buffer): string[] {
  const zip = new PizZip(docxBytes);
  const document = zip.file("word/document.xml");
  if (!document) {
    throw new Error("DOCX archive is missing word/document.xml.");
  }
  const xml = document.asText();
  const paragraphs: string[] = [];
  for (const block of xml.split(/<w:p[\s>]/)) {
    const runs: string[] = [];
    const runPattern = /<w:t[^>]*>([^<]*)<\/w:t>/g;
    let match: RegExpExecArray | null;
    while ((match = runPattern.exec(block)) !== null) {
      runs.push(
        (match[1] as string)
          .replace(/&lt;/g, "<")
          .replace(/&gt;/g, ">")
          .replace(/&quot;/g, '"')
          .replace(/&apos;/g, "'")
          .replace(/&amp;/g, "&"),
      );
    }
    if (runs.length > 0) {
      paragraphs.push(runs.join(""));
    }
  }
  return paragraphs;
}
